CREATE OR REPLACE FUNCTION public.get_today_quota() RETURNS public.daily_quota LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE d date := (now() AT TIME ZONE 'UTC')::date; q public.daily_quota; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; INSERT INTO public.daily_quota(day,target) VALUES(d,least(20000,10000+100*(SELECT count(*) FROM public.players))) ON CONFLICT(day) DO NOTHING; SELECT * INTO q FROM public.daily_quota WHERE day=d; RETURN q; END; $$;
REVOKE ALL ON FUNCTION public.get_today_quota() FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.get_today_quota() TO authenticated;
CREATE TABLE public.blueprint_jobs (owner_id uuid NOT NULL, decor_key text NOT NULL, tool_id text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), ready_at timestamptz NOT NULL DEFAULT (now()+interval '16 hours'), PRIMARY KEY(owner_id,decor_key));
GRANT SELECT ON public.blueprint_jobs TO authenticated; GRANT ALL ON public.blueprint_jobs TO service_role;
ALTER TABLE public.blueprint_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY blueprint_owner_read ON public.blueprint_jobs FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE OR REPLACE FUNCTION public.blueprint_action(decor text, action text, tool text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); j public.blueprint_jobs; p public.players; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT * INTO p FROM public.players WHERE id=uid FOR UPDATE; IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p.room) x WHERE x->>'key'=decor AND x->>'id'='blueprint') THEN RAISE EXCEPTION 'Blueprint Machine not placed'; END IF; SELECT * INTO j FROM public.blueprint_jobs WHERE owner_id=uid AND decor_key=decor FOR UPDATE; IF action='start' THEN IF j.owner_id IS NOT NULL THEN RAISE EXCEPTION 'Already crafting'; END IF; IF tool IS NULL OR tool NOT IN('axe','pistol','health','adrenaline','navigator','flashcharge','papermap','pipe','knife','radar','tear') THEN RAISE EXCEPTION 'Unknown tool'; END IF; INSERT INTO public.blueprint_jobs(owner_id,decor_key,tool_id) VALUES(uid,decor,tool) RETURNING * INTO j; RETURN to_jsonb(j); ELSIF action='cancel' THEN DELETE FROM public.blueprint_jobs WHERE owner_id=uid AND decor_key=decor; RETURN '{}'::jsonb; ELSIF action='claim' THEN IF j.owner_id IS NULL OR now()<j.ready_at THEN RAISE EXCEPTION 'Not ready'; END IF; DELETE FROM public.blueprint_jobs WHERE owner_id=uid AND decor_key=decor; RETURN jsonb_build_object('tool_id',j.tool_id); ELSE RAISE EXCEPTION 'Unknown action'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.blueprint_action(text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.blueprint_action(text,text,text) TO authenticated;